function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 80);
  ctx.stroke();

  // draw harmony spheres
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50 * Math.sin(t), H/2 - 50 + 20 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.sin(t + Math.PI), H/2 - 50 + 20 * Math.cos(t + Math.PI), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 30 * Math.sin(t + Math.PI/2), H/2 + 50 + 10 * Math.cos(t + Math.PI/2), 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 30 * Math.sin(t - Math.PI/2), H/2 + 50 + 10 * Math.cos(t - Math.PI/2), 15, 0, 2 * Math.PI);
  ctx.stroke();

  // draw pythagoras numbers
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('a² + b² = c²', W/2, H/2 + 150 + 10 * Math.sin(t));

  ctx.restore();
}
